# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def check_inside(worked: Iterable[Span], opening: Span):
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(
                f"outside opening hours: {format_span(span)}"
            )


def uncovered(worked: Iterable[Span], opening: Span) -> List[Span]:
    edges = [opening.start]
    for span in merge_spans(worked):
        edges += [span.start, span.end]
    edges.append(opening.end)
    pairs = zip(edges[::2], edges[1::2])
    return [Span(a, b) for a, b in pairs if a < b]


def gap_labels(worked: Iterable[Span], opening: Span) -> List[str]:
    """Labels such as 'gap 12:00-13:00 (60 min)', in time order."""
    worked = list(worked)
    check_inside(worked, opening)
    return [
        f"gap {format_span(gap)} ({gap.minutes} min)"
        for gap in uncovered(worked, opening)
    ]

