# owner: platform
import unittest

from hourglass.gaps import gap_labels
from hourglass.models import Span

OPEN = Span(540, 1020)


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            gap_labels(worked, OPEN), ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            gap_labels([Span(600, 960)], OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 16:00-17:00 (60 min)"]
        )

    def test_overlaps_leave_no_gap(self):
        worked = [Span(540, 800), Span(700, 1020)]
        self.assertEqual(gap_labels(worked, OPEN), [])

    def test_nobody_working(self):
        self.assertEqual(
            gap_labels([], OPEN), ["gap 09:00-17:00 (480 min)"]
        )

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(500, 600)], OPEN)
